#!/usr/bin/env python3
"""Project survey tables from committed quality records and evaluated receipts."""
import json
import pathlib
import statistics

base = pathlib.Path('dev/bench_results/c077a88b')
prep = base / 'v3-preparation'
quality = json.loads((prep / 'validation.json').read_text())
lines = ['# LDPC survey evidence tables', '', '> **Diátaxis Type:** Reference', '',
         'Generated by `dev/active/c077a88b/survey/summarize.py`; source paths accompany each table.', '',
         '## Quality on identical recorded inputs', '',
         'Source: `v3-preparation/validation.json`. FER uses Wilson 95%; BER uses independent-frame Hoeffding 95%.',
         f'Every row has {quality["frames"]} distinct frames, including both codeword classes. Repeated timing',
         'executions reuse this same evidence and do not add quality samples.', '',
         '| Code | Arm | FER (errors/frames) | FER interval | BER (errors/bits) | BER interval | Iterations mean / p50 / p90 / max | Native wave | Process RSS bytes |',
         '|---|---|---|---|---|---|---|---|---|']
for group in quality['groups']:
    for arm in group['arms']:
        q = arm['quality']; it = q['iterations']
        interval = lambda key: f"[{q[key][0]:.6g}, {q[key][1]:.6g}]"
        lines.append(f"| {group['id']} | {arm['name']} | {q['fer']:.6g} ({q['frame_errors']}/{q['frames']}) | {interval('fer_interval')} | {q['ber']:.6g} ({q['bit_errors']}/{q['bits']}) | {interval('ber_interval')} | {it['mean']:.3f} / {it['p50']} / {it['p90']} / {it['max']} | {q['settings']['batch_size']} | {q['memory_bytes']} |")
lines += ['', 'Layered iterations are ladder upper bounds over native waves, not exact per-frame',
          'iteration counts. RSS is the observed process high-water mark, not decoder allocation size.', '',
          '## Matched-algorithm timing', '']
for family in ['matched-algorithm', 'quality-compatible']:
    if family == 'quality-compatible': lines += ['## Quality-compatible timing', '']
    receipts = sorted(base.glob('*-ldpc-' + family + '-*/receipt.json'))
    if not receipts:
        lines += ['No finalized receipt is available.', '']
    for path in receipts:
        receipt = json.loads(path.read_text())
        summary = json.loads((path.parent / 'acceptance-summary.json').read_text())
        plan = json.loads((path.parent / 'plan.json').read_text())
        cases = {c['cell_id']: c['case'] for c in plan['cells']}
        verdicts = {c['cell_id']: c for c in summary['cells']}
        if not path.parent.name.startswith('v3-'):
            lines += [f"Immutable superseded v1 attempt: `{path.parent.name}/README.md`; see `superseded-v1-evidence.json`. It supplies no v3 resolution or confirmatory claim.", '']
            continue
        lines += [f"Source: `{path.parent.name}/receipt.json` and its independently recomputed acceptance summary.",
                  f"Label: **{receipt['label']}**; acceptance: **{summary['verdict']}**. This survey adopts no production implementation.",
                  f"Ledger-derived attempt alpha: {summary['family']['family_alpha']}; reserved comparisons: {summary['family']['comparisons']}.", '',
                  '| Cell | Pairs | Useful frames/call | Baseline median ms/call | Candidate median ms/call | Speedup [family interval] | Confidence | Outcome |',
                  '|---|---|---|---|---|---|---|---|']
        for cell in receipt['cells']:
            v = verdicts[cell['cell_id']]; ci = v.get('interval'); pairs = cell['pairs']
            if not pairs:
                lines.append(f"| {cell['cell_id']} | 0 | — | — | — | — | — | {v['outcome']} |")
                continue
            med = lambda name: statistics.median(p[name]['ns_per_call'] for p in pairs) / 1e6
            text = f"{ci['estimate']:.4g} [{ci['lower']:.4g}, {ci['upper']:.4g}]" if ci else 'unavailable'
            lines.append(f"| {cell['cell_id']} | {len(pairs)} | {cases[cell['cell_id']]['batch_size']} | {med('baseline'):.3f} | {med('candidate'):.3f} | {text} | {ci['confidence'] if ci else '—'} | {v['outcome']} |")
        lines += ['', 'A `quality-incompatible` outcome means the frozen paired bound does not establish',
                  'quality non-inferiority; it does not by itself establish worse decoder quality.', '', 'Call latency includes recorded AList loading, matrix and decoder construction, conversion, output and destruction. The median',
                  'columns are descriptive summaries of the recorded executions; the paired bootstrap',
                  'interval estimates the implementation ratio. Throughput is useful frames per call',
                  'divided by call latency. A native SIMD wave is not counted as one useful frame.', '']
        lines += ['Untimed setup/conversion diagnostics from the same receipt (median across pairs):', '',
                  '| Cell | Arm | Matrix + decoder setup ms | Full-bundle preflight pack ms | Additional unpack / fill / dispatch ms |',
                  '|---|---|---|---|---|']
        for cell in receipt['cells']:
            for arm_name in ['baseline', 'candidate']:
                conversions = [p[arm_name]['conversion'] for p in cell['pairs']]
                if not conversions:
                    continue
                median_ms = lambda key: statistics.median(c[key] for c in conversions) / 1e6
                extra = ' / '.join(f'{median_ms(key):.3f}' for key in ['unpack_ns', 'batch_fill_ns', 'dispatch_ns'])
                lines.append(f"| {cell['cell_id']} | {arm_name} | {median_ms('setup_ns'):.3f} | {median_ms('pack_ns'):.3f} | {extra} |")
        lines += ['', 'These diagnostics are outside the calibrated windows and are not additive',
                  'components of the timed median. gf2 preflight packs the full input bundle;',
                  'the timed body separately converts its declared batch. AFF3CT converts and',
                  'reorders inside its decode call. Zero additional costs therefore mean no',
                  'separate stage, not free conversion. All measured batches are already filled;',
                  'arrival queueing delay is unmeasured.', '']
(base / 'tables.md').write_text('\n'.join(lines) + '\n')
